from __future__ import annotations

from fastapi import APIRouter, Request
from fastapi.responses import HTMLResponse

from .branding import ENDORSEMENT, PRODUCT_NAME, TAGLINE

router = APIRouter()


@router.get("/creative-house", response_class=HTMLResponse)
def creative_house(request: Request):
    member = getattr(request.state, "member", None)
    plan = getattr(getattr(member, "plan", None), "id", "member")
    html = r"""<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<meta name="theme-color" content="#05040b">
<title>__PRODUCT__ — Creative House</title>
<style>
:root{--bg:#04050b;--panel:#0c0e1add;--panel2:#111528;--line:#ffffff1d;--gold:#f3c76d;--violet:#a86cff;--cyan:#5ce8ff;--pink:#ff72cd;--green:#78dda7;--text:#fff;--muted:#b9bed1;--danger:#ff8e9e}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 12% 0,#33134c,transparent 30%),radial-gradient(circle at 88% 4%,#0d3753,transparent 28%),linear-gradient(#03040a,#070710 60%,#020308);color:var(--text);font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;min-height:100vh}a{color:inherit;text-decoration:none}button,input,textarea,select{font:inherit}.wrap{width:min(1440px,calc(100% - 28px));margin:auto}.nav{position:sticky;top:0;z-index:20;background:#05060bdd;backdrop-filter:blur(20px);border-bottom:1px solid var(--line)}.navin{min-height:72px;display:flex;align-items:center;justify-content:space-between;gap:16px}.brand{display:flex;align-items:center;gap:11px;font-weight:900}.brand img{width:46px;height:46px;border-radius:14px;border:1px solid #ffffff2a;box-shadow:0 0 28px #a86cff44}.brand small{display:block;font-size:.62rem;color:var(--gold);letter-spacing:.07em;text-transform:uppercase;margin-top:2px}.navlinks{display:flex;gap:7px;flex-wrap:wrap}.btn{border:1px solid var(--line);background:#ffffff08;color:#fff;padding:10px 13px;border-radius:12px;font-weight:800;cursor:pointer}.btn.primary{border:0;background:linear-gradient(110deg,#fff0ae,var(--gold),#c69cff);color:#170d20}.btn:disabled{opacity:.5;cursor:not-allowed}.hero{padding:46px 0 24px;display:flex;align-items:end;justify-content:space-between;gap:24px}.eyebrow{font-size:.72rem;color:var(--gold);font-weight:900;letter-spacing:.17em;text-transform:uppercase}.hero h1{font-size:clamp(2.5rem,6vw,5rem);line-height:.93;letter-spacing:-.055em;margin:.13em 0 .2em}.hero h1 span{background:linear-gradient(95deg,#fff,var(--gold),var(--pink),var(--cyan));background-clip:text;color:transparent}.lead{color:var(--muted);max-width:850px;line-height:1.6}.plan{border:1px solid #f3c76d45;background:#f3c76d0a;border-radius:999px;padding:8px 12px;color:var(--gold);font-weight:850;white-space:nowrap}.projectbar{display:grid;grid-template-columns:1.1fr 1.3fr 2fr auto auto;gap:9px;padding:14px;border:1px solid var(--line);border-radius:20px;background:#0b0c16cc;margin:18px 0}.field{width:100%;border:1px solid var(--line);background:#080a14;color:#fff;border-radius:12px;padding:11px 12px;outline:none}.field:focus{border-color:#9f71ff88;box-shadow:0 0 0 3px #9f71ff18}textarea.field{min-height:95px;resize:vertical}.caps{display:grid;grid-template-columns:repeat(7,1fr);gap:8px;margin:12px 0 20px}.cap{border:1px solid var(--line);border-radius:15px;padding:12px;background:#ffffff06}.cap strong{display:block;text-transform:capitalize}.cap small{display:block;margin-top:5px;color:var(--muted)}.cap.connected{border-color:#78dda74a}.cap.partial{border-color:#f3c76d4f}.cap.integration_slot{border-color:#a86cff4d}.workspace{display:grid;grid-template-columns:1.1fr .9fr;gap:14px;padding-bottom:64px}.panel{border:1px solid var(--line);border-radius:22px;background:linear-gradient(145deg,#111426dd,#080a14e8);padding:18px;min-width:0}.panel h2{margin:5px 0 4px;font-size:1.25rem}.muted{color:var(--muted);line-height:1.55}.forms{display:grid;grid-template-columns:1fr 1fr;gap:12px}.formbox{border:1px solid var(--line);border-radius:17px;padding:14px;background:#ffffff04}.formbox h3{font-size:.94rem;margin:0 0 11px}.stack{display:grid;gap:8px}.row{display:grid;grid-template-columns:1fr 1fr;gap:8px}.list{display:grid;gap:8px;margin-top:14px;max-height:520px;overflow:auto;padding-right:3px}.item{border:1px solid var(--line);border-radius:15px;padding:12px;background:#070912}.itemtop{display:flex;justify-content:space-between;gap:10px}.chip{display:inline-flex;border:1px solid var(--line);border-radius:999px;padding:4px 7px;font-size:.68rem;color:#dcdbea;margin:3px 4px 0 0}.chip.gold{color:var(--gold);border-color:#f3c76d3d}.chip.good{color:var(--green);border-color:#78dda73d}.chip.wait{color:#ceb0ff;border-color:#a86cff45}.id{font:600 .69rem ui-monospace,SFMono-Regular,Menlo,monospace;color:#8e94aa;word-break:break-all}.directive{border-left:3px solid var(--violet)}.directive.ready{border-left-color:var(--green)}.notice{display:none;margin:10px 0;padding:11px 13px;border-radius:13px;border:1px solid var(--line);background:#ffffff07}.notice.show{display:block}.notice.error{border-color:#ff8e9e52;color:#ffd6dc}.empty{border:1px dashed #ffffff27;border-radius:16px;padding:20px;text-align:center;color:var(--muted)}.footer{padding:30px 0 45px;border-top:1px solid var(--line);color:var(--muted);font-size:.85rem}@media(max-width:1100px){.projectbar{grid-template-columns:1fr 1fr}.projectbar .wide{grid-column:1/-1}.caps{grid-template-columns:repeat(4,1fr)}.workspace{grid-template-columns:1fr}}@media(max-width:720px){.hero{align-items:flex-start;flex-direction:column}.projectbar,.forms,.row{grid-template-columns:1fr}.caps{grid-template-columns:repeat(2,1fr)}.navlinks .optional{display:none}.brand small{display:none}}
</style>
</head>
<body>
<nav class="nav"><div class="wrap navin"><a class="brand" href="/"><img src="/brand/pulsar-frequency-house-logo.svg" alt="__PRODUCT__ logo"><span>__PRODUCT__<small>__ENDORSEMENT__</small></span></a><div class="navlinks"><a class="btn optional" href="/studio">Music Studio</a><a class="btn optional" href="/production-suite">Production Suite</a><a class="btn optional" href="/command-center">ESP Hub</a><a class="btn" href="/dashboard">Dashboard</a></div></div></nav>
<main class="wrap">
<section class="hero"><div><div class="eyebrow">Aura Unified Creative Workspace</div><h1>One project. <span>Every medium.</span></h1><div class="lead">Build the editable DNA of a song, video, image, voice performance or campaign in one place. Aura directives preserve what to change, what to keep and which references belong to the project while renderer integrations remain explicit and truthful.</div></div><div class="plan">__PLAN__ plan</div></section>
<div id="notice" class="notice"></div>
<section class="projectbar"><input id="projectName" class="field" placeholder="Project ID, e.g. sparkles-video"><input id="projectTitle" class="field" placeholder="Project title"><input id="projectIntent" class="field wide" placeholder="Creative intent — what are we making?"><button class="btn primary" onclick="initializeProject()">Initialize</button><button class="btn" onclick="loadProject()">Load</button></section>
<section id="capabilities" class="caps"></section>
<section class="workspace">
<div class="panel"><div class="eyebrow">Project DNA</div><h2>Creative elements & references</h2><p class="muted">Elements are individually addressable pieces Aura can later target: a chorus, vocal, scene, cover image, background, camera sequence or any other creative component.</p><div class="forms"><div class="formbox"><h3>Add creative element</h3><div class="stack"><div class="row"><select id="elementKind" class="field"><option>music</option><option>audio</option><option>voice</option><option>video</option><option>image</option><option>text</option></select><input id="elementRole" class="field" placeholder="Role, e.g. final chorus"></div><input id="elementLabel" class="field" placeholder="Element label"><input id="elementSource" class="field" placeholder="Existing asset/reference ID (optional)"><textarea id="elementPrompt" class="field" placeholder="Creative description or prompt"></textarea><button class="btn primary" onclick="addElement()">Add element</button></div></div><div class="formbox"><h3>Attach authorised reference</h3><div class="stack"><div class="row"><select id="referenceKind" class="field"><option>audio</option><option>music</option><option>voice</option><option>video</option><option>image</option><option>text</option><option>reference</option></select><input id="referenceLabel" class="field" placeholder="Reference label"></div><input id="referenceSource" class="field" placeholder="Asset ID, local project ref or authorised URI"><input id="referenceUsage" class="field" placeholder="How Aura should use it"><label class="muted"><input id="referenceRights" type="checkbox"> I confirm I have the right or authorization to use this reference.</label><button class="btn" onclick="addReference()">Attach reference</button></div></div></div><div id="elements" class="list"><div class="empty">Load or initialize a project to see its editable creative DNA.</div></div></div>
<div class="panel"><div class="eyebrow">Aura Direction Layer</div><h2>Tell Aura exactly what changes</h2><p class="muted">A directive records the intended operation and its scope. Connected music/audio routes can become renderer-ready; video/image requests remain safely planned until those render adapters are actually connected.</p><div class="formbox"><div class="stack"><div class="row"><select id="operation" class="field"><option>create</option><option>revise</option><option>replace</option><option>extend</option><option>transform</option><option>arrange</option><option>mix</option><option>master</option><option>sync</option><option>storyboard</option><option>style</option><option>analyze</option></select><select id="targetKind" class="field"><option value="">Infer from element</option><option>music</option><option>audio</option><option>voice</option><option>video</option><option>image</option><option>text</option></select></div><input id="targetIds" class="field" placeholder="Target element IDs, comma separated (optional)"><input id="preserveIds" class="field" placeholder="Element IDs Aura must preserve (optional)"><input id="referenceIds" class="field" placeholder="Reference IDs to use (optional)"><textarea id="instruction" class="field" placeholder="Example: Keep my lead vocal exactly as it is. Rebuild only the final chorus with larger drums, wider guitars and cinematic strings."></textarea><button class="btn primary" onclick="addDirective()">Add Aura directive</button></div></div><div id="directives" class="list"><div class="empty">Aura directives will appear here with their real execution state.</div></div></div>
</section>
</main>
<footer class="footer"><div class="wrap"><strong>__PRODUCT__</strong> · __TAGLINE__<br>__ENDORSEMENT__</div></footer>
<script>
let manifest=null;let capabilities={};
const qs=id=>document.getElementById(id);const splitIds=value=>value.split(',').map(x=>x.trim()).filter(Boolean);
function project(){return qs('projectName').value.trim()}
function notice(message,error=false){const box=qs('notice');box.textContent=message;box.className='notice show'+(error?' error':'');window.clearTimeout(window.__noticeTimer);window.__noticeTimer=setTimeout(()=>box.className='notice',6500)}
async function api(path,options={}){const res=await fetch(path,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(options.headers||{})},...options});let body={};try{body=await res.json()}catch(e){}if(!res.ok)throw new Error(body.detail||`Request failed (${res.status})`);return body}
async function loadCapabilities(){try{const data=await api('/creative/capabilities');capabilities=data.capabilities||{};renderCapabilities()}catch(e){notice(e.message,true)}}
function renderCapabilities(){const icons={music:'🎵',audio:'🎚️',voice:'🎙️',video:'🎬',image:'🎨',text:'✍️',reference:'📎'};qs('capabilities').innerHTML=Object.entries(capabilities).map(([kind,c])=>`<div class="cap ${c.state}"><strong>${icons[kind]||'✨'} ${kind}</strong><small>${c.state.replaceAll('_',' ')} · ${c.renderer_route}</small></div>`).join('')}
async function initializeProject(){if(!project())return notice('Enter a project ID first.',true);const title=qs('projectTitle').value.trim()||project();try{const data=await api(`/creative/projects/${encodeURIComponent(project())}/initialize`,{method:'POST',body:JSON.stringify({title,project_intent:qs('projectIntent').value.trim()})});manifest=data.manifest;capabilities=data.capabilities||capabilities;render();notice('Creative project DNA initialized.') }catch(e){notice(e.message,true)}}
async function loadProject(){if(!project())return notice('Enter a project ID first.',true);try{const data=await api(`/creative/projects/${encodeURIComponent(project())}/manifest`);manifest=data.manifest;capabilities=data.capabilities||capabilities;qs('projectTitle').value=manifest.title||'';qs('projectIntent').value=manifest.project_intent||'';render();notice('Project loaded.') }catch(e){notice(e.message,true)}}
async function addElement(){if(!manifest)return notice('Load or initialize a project first.',true);const label=qs('elementLabel').value.trim();if(!label)return notice('Give the element a label.',true);try{const source=qs('elementSource').value.trim();const data=await api(`/creative/projects/${encodeURIComponent(project())}/elements`,{method:'POST',body:JSON.stringify({kind:qs('elementKind').value,label,role:qs('elementRole').value.trim(),source_type:source?'reference':'generated',source_ref:source||null,prompt:qs('elementPrompt').value.trim()})});manifest=data.manifest;qs('elementLabel').value='';qs('elementRole').value='';qs('elementSource').value='';qs('elementPrompt').value='';render();notice('Creative element added and addressable by Aura.')}catch(e){notice(e.message,true)}}
async function addReference(){if(!manifest)return notice('Load or initialize a project first.',true);if(!qs('referenceRights').checked)return notice('Rights/authorization confirmation is required.',true);try{const data=await api(`/creative/projects/${encodeURIComponent(project())}/references`,{method:'POST',body:JSON.stringify({kind:qs('referenceKind').value,label:qs('referenceLabel').value.trim(),source_ref:qs('referenceSource').value.trim(),usage:qs('referenceUsage').value.trim()||'creative reference',rights_confirmed:true})});manifest=data.manifest;qs('referenceLabel').value='';qs('referenceSource').value='';qs('referenceUsage').value='';qs('referenceRights').checked=false;render();notice('Authorised reference attached to project context.')}catch(e){notice(e.message,true)}}
async function addDirective(){if(!manifest)return notice('Load or initialize a project first.',true);const instruction=qs('instruction').value.trim();if(!instruction)return notice('Tell Aura what you want changed or created.',true);try{const targetKind=qs('targetKind').value||null;const data=await api(`/creative/projects/${encodeURIComponent(project())}/directives`,{method:'POST',body:JSON.stringify({instruction,input_mode:'text',operation:qs('operation').value,target_kind:targetKind,target_element_ids:splitIds(qs('targetIds').value),preserve_element_ids:splitIds(qs('preserveIds').value),reference_ids:splitIds(qs('referenceIds').value)})});manifest=data.manifest;qs('instruction').value='';render();notice(data.truthful_execution_state.note)}catch(e){notice(e.message,true)}}
function render(){renderCapabilities();if(!manifest)return;const refs=(manifest.references||[]).map(r=>`<div class="item"><div class="itemtop"><strong>📎 ${escapeHtml(r.label)}</strong><span class="chip gold">${r.kind}</span></div><div class="muted">${escapeHtml(r.usage||'')}</div><div class="id">${r.id}</div></div>`);const els=(manifest.elements||[]).map(e=>`<div class="item"><div class="itemtop"><strong>${escapeHtml(e.label)}</strong><span class="chip ${e.status==='ready'?'good':''}">${e.kind} · ${e.status}</span></div><div class="muted">${escapeHtml(e.role||e.prompt||'No additional direction yet.')}</div><div class="id">${e.id}</div></div>`);qs('elements').innerHTML=[...els,...refs].join('')||'<div class="empty">No elements yet. Add the first editable piece of this creative project.</div>';const dirs=[...(manifest.directives||[])].reverse().map(d=>`<div class="item directive ${d.status==='ready_for_renderer'?'ready':''}"><div class="itemtop"><strong>${d.operation} → ${d.target_kind||'project'}</strong><span class="chip ${d.status==='ready_for_renderer'?'good':'wait'}">${d.status.replaceAll('_',' ')}</span></div><div class="muted">${escapeHtml(d.instruction)}</div><div><span class="chip">${d.capability_state.replaceAll('_',' ')}</span><span class="chip">${d.renderer_route||'Aura planning'}</span></div><div class="id">${d.id}</div></div>`);qs('directives').innerHTML=dirs.join('')||'<div class="empty">No directives yet. Tell Aura what should happen next.</div>'}
function escapeHtml(value){return String(value??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
const requested=new URLSearchParams(location.search).get('project');if(requested){qs('projectName').value=requested;loadProject()}loadCapabilities();
</script>
</body></html>"""
    return HTMLResponse(
        html.replace("__PRODUCT__", PRODUCT_NAME)
        .replace("__ENDORSEMENT__", ENDORSEMENT)
        .replace("__TAGLINE__", TAGLINE)
        .replace("__PLAN__", plan.upper())
    )
